precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 1
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _Time;
uniform 	vec4 _ProjectionParams;
uniform 	float _UCenter;
uniform 	float _VCenter;
uniform 	float _DistortionSwitch;
uniform 	float _BlurStr;
uniform 	float _BlurMatCus;
uniform 	float _BlurSwitch;
uniform 	float _CABlurSwitch;
uniform 	vec4 _Color0;
uniform 	vec4 _Color1;
uniform 	float _BWShape;
uniform 	float _BWSmooth;
uniform 	float _BW;
uniform mediump sampler2D _DisTex;
uniform highp sampler2D _GrabScreen0;





vec4 u_xlat0;
mediump float u_xlat16_0;
vec4 u_xlat1;
vec4 u_xlat2;
vec4 u_xlat3;
vec3 u_xlat4;
vec3 u_xlat5;
float u_xlat7;
vec2 u_xlat8;
vec2 u_xlat12;
float u_xlat13;
vec2 u_xlat14;
float u_xlat18;
void main()
{
    u_xlat0.x = vs_TEXCOORD4.z * _Time.y;
    u_xlat0.xy = u_xlat0.xx * vs_TEXCOORD4.xy + vs_TEXCOORD3.xy;
    u_xlat16_0 = texture2D(_DisTex, u_xlat0.xy).x;
    u_xlat0.x = u_xlat16_0 * vs_TEXCOORD4.w;
    u_xlat1.x = vs_TEXCOORD3.x * _UCenter;
    u_xlat1.y = vs_TEXCOORD3.y * _VCenter;
    u_xlat0.xy = vec2(vec2(_DistortionSwitch, _DistortionSwitch)) * u_xlat0.xx + u_xlat1.xy;
    u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlat12.x = vs_TEXCOORD1.w * 0.5;
    u_xlat18 = (-vs_TEXCOORD1.w) * 0.5 + vs_TEXCOORD1.y;
    u_xlat1.y = u_xlat18 * _ProjectionParams.x + u_xlat12.x;
    u_xlat1.x = vs_TEXCOORD1.x;
    u_xlat12.xy = u_xlat1.xy / vs_TEXCOORD1.ww;
    u_xlat0.xy = (-u_xlat0.xy) + u_xlat12.xy;
    u_xlat1.xy = u_xlat0.xy * vec2(0.00999999978, 0.00999999978);
    u_xlat13 = _BlurMatCus * vs_TEXCOORD2.y + _BlurStr;
    u_xlat2.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat12.xy;
    u_xlat14.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat2.xy;
    u_xlat3 = texture2D(_GrabScreen0, u_xlat2.xy);
    u_xlat2.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat14.xy;
    u_xlat4.xyz = texture2D(_GrabScreen0, u_xlat14.xy).xyz;
    u_xlat4.xyz = u_xlat3.xyz + u_xlat4.xyz;
    u_xlat5.xyz = texture2D(_GrabScreen0, u_xlat2.xy).xyz;
    u_xlat2.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat2.xy;
    u_xlat4.xyz = u_xlat4.xyz + u_xlat5.xyz;
    u_xlat5.xyz = texture2D(_GrabScreen0, u_xlat2.xy).xyz;
    u_xlat2.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat2.xy;
    u_xlat4.xyz = u_xlat4.xyz + u_xlat5.xyz;
    u_xlat5.xyz = texture2D(_GrabScreen0, u_xlat2.xy).xyz;
    u_xlat2.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat2.xy;
    u_xlat4.xyz = u_xlat4.xyz + u_xlat5.xyz;
    u_xlat5.xyz = texture2D(_GrabScreen0, u_xlat2.xy).xyz;
    u_xlat2.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat2.xy;
    u_xlat1.xy = (-u_xlat1.xy) * vec2(u_xlat13) + u_xlat2.xy;
    u_xlat2.xyz = texture2D(_GrabScreen0, u_xlat2.xy).xyz;
    u_xlat1.xyz = texture2D(_GrabScreen0, u_xlat1.xy).xyz;
    u_xlat4.xyz = u_xlat4.xyz + u_xlat5.xyz;
    u_xlat2.xyz = u_xlat2.xyz + u_xlat4.xyz;
    u_xlat1.xyz = u_xlat1.xyz + u_xlat2.xyz;
    u_xlat1.xyz = u_xlat1.xyz * vec3(0.125, 0.125, 0.125);
    u_xlat1.w = 1.0;
    u_xlat1 = (-u_xlat3) + u_xlat1;
    u_xlat1 = vec4(_BlurSwitch) * u_xlat1 + u_xlat3;
    u_xlat2.x = vs_TEXCOORD2.x * 0.00999999978;
    u_xlat12.xy = (-u_xlat2.xx) * u_xlat0.xy + u_xlat12.xy;
    u_xlat8.xy = (-u_xlat2.xx) * u_xlat0.xy + u_xlat12.xy;
    u_xlat3.x = texture2D(_GrabScreen0, u_xlat12.xy).x;
    u_xlat0.xy = (-u_xlat2.xx) * u_xlat0.xy + u_xlat8.xy;
    u_xlat3.y = texture2D(_GrabScreen0, u_xlat8.xy).y;
    u_xlat3.z = texture2D(_GrabScreen0, u_xlat0.xy).z;
    u_xlat3.w = 1.0;
    u_xlat0 = u_xlat1 + (-u_xlat3);
    u_xlat0 = vec4(vec4(_CABlurSwitch, _CABlurSwitch, _CABlurSwitch, _CABlurSwitch)) * u_xlat0 + u_xlat3;
    u_xlat1.x = dot(u_xlat0.xyz, vec3(0.298999995, 0.587000012, 0.114));
    u_xlat1.x = u_xlat1.x + (-_BWShape);
    u_xlat7 = float(1.0) / _BWSmooth;
    u_xlat1.x = u_xlat7 * u_xlat1.x;
    u_xlat1.x = clamp(u_xlat1.x, 0.0, 1.0);
    u_xlat7 = u_xlat1.x * -2.0 + 3.0;
    u_xlat1.x = u_xlat1.x * u_xlat1.x;
    u_xlat1.x = u_xlat1.x * u_xlat7;
    u_xlat7 = u_xlat1.x * -2.0 + 1.0;
    u_xlat1.x = vs_TEXCOORD2.z * u_xlat7 + u_xlat1.x;
    u_xlat2 = (-_Color0) + _Color1;
    u_xlat1 = u_xlat1.xxxx * u_xlat2 + _Color0;
    u_xlat1 = (-u_xlat0) + u_xlat1;
    u_xlat0 = vec4(vec4(_BW, _BW, _BW, _BW)) * u_xlat1 + u_xlat0;
    gl_FragColor = u_xlat0;
    return;
}
